use super::*;
use semio_framework_os_kernel::{sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteValue,SqliteSnapshotPhase},ArtifactSqliteSnapshot};
fn unsigned(object:&mut serde_json::Value,fields:&[&str]){for field in fields{let value=object[*field].as_str().unwrap().parse::<u64>().unwrap();object[*field]=value.into();}}
fn fixture()->Mp4Snapshot{let mut value:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();unsigned(&mut value["movie"],&["creationTime","modificationTime","duration"]);for track in value["tracks"].as_array_mut().unwrap(){unsigned(&mut track["metadata"],&["creationTime","modificationTime","duration","mediaDuration","mediaCreationTime","mediaModificationTime"]);for edit in track["metadata"]["edits"].as_array_mut().unwrap(){unsigned(edit,&["segmentDuration"]);edit["mediaTime"]=edit["mediaTime"].as_str().unwrap().parse::<i64>().unwrap().into();}if !track["codec"]["hevc"].is_null(){unsigned(&mut track["codec"]["hevc"],&["generalConstraintIndicatorFlags"]);}}<Mp4Snapshot as dsl::FromValue>::from_value(dsl::DslValue::from(value)).unwrap()}
fn roundtrip(snapshot:&Mp4Snapshot)->Mp4Snapshot{let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();Mp4Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
#[test]
fn sqlite_snapshot_mp4_full_neutral_widths_configs_optionals_and_codec_formats(){let snapshot=fixture();assert_eq!(roundtrip(&snapshot),snapshot);for format in[Mp4CodecFormat::Avc1,Mp4CodecFormat::Avc3,Mp4CodecFormat::Hvc1,Mp4CodecFormat::Hev1,Mp4CodecFormat::Jpeg,Mp4CodecFormat::Mjpa]{let mut snapshot=snapshot.clone();snapshot.tracks[0].codec.format=format;snapshot.tracks[0].metadata.color.as_mut().unwrap().full_range=None;assert_eq!(roundtrip(&snapshot),snapshot);snapshot.tracks[0].metadata.color.as_mut().unwrap().full_range=Some(true);assert_eq!(roundtrip(&snapshot),snapshot);}let mut empty=Mp4Snapshot::default();empty.schema.clear();empty.ftyp.major_brand.clear();assert_eq!(roundtrip(&empty),empty);}
#[test]
fn sqlite_snapshot_mp4_independent_sqlite_queries_and_retained_entity_edits(){use std::{io::Write,process::{Command,Stdio}};let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));db.query('SELECT 1').safeIntegers(true);if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const row=db.query('SELECT m.creation_time,h.general_constraint_indicator_flags,v.color_table_id FROM mp4_track t JOIN mp4_track_metadata m ON m.id=t.id JOIN mp4_codec c ON c.id=t.id JOIN mp4_hevc_config h ON h.id=c.id JOIN mp4_visual_sample_entry v ON v.id=m.id').get();if(row.creation_time!=='18446744073709551615'||row.general_constraint_indicator_flags!=='18446744073709551615'||row.color_table_id!==-32768)throw Error('wide domain');if(db.query('SELECT count(*) AS n FROM mp4_avc_sps WHERE length(data)=0').get().n!==1||db.query('SELECT count(*) AS n FROM mp4_track WHERE track_id=4294967295').get().n!==2)throw Error('occurrences');db.run(\"UPDATE mp4_movie SET creation_time='9007199254740993',title=NULL,encoder=''\");db.run(\"UPDATE mp4_hevc_config SET general_constraint_indicator_flags='9223372036854775808'\");db.run('UPDATE mp4_visual_sample_entry SET color_table_id=123 WHERE id=1');db.run(\"UPDATE mp4_sample SET data=X'FF00',cts_offset=-123,sync=0 WHERE id=1\");db.run('UPDATE mp4_movie_matrix SET value=42 WHERE ordinal=8');await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.movie.creation_time=9007199254740993;expected.movie.title=None;expected.movie.encoder=Some(String::new());expected.tracks[0].codec.hevc.as_mut().unwrap().general_constraint_indicator_flags=9223372036854775808;expected.tracks[0].metadata.visual.color_table_id=123;expected.tracks[0].samples[0].data=vec![255,0];expected.tracks[0].samples[0].cts_offset=-123;expected.tracks[0].samples[0].sync=false;expected.movie.matrix[8]=42;assert_eq!(Mp4Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}
#[test]
fn sqlite_snapshot_mp4_refuses_invalid_owners_ordinals_widths_singletons_and_decimal_words(){let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for(table,column,value)in[("mp4_track",1,SqliteValue::Integer(99)),("mp4_track",2,SqliteValue::Integer(99)),("mp4_codec",1,SqliteValue::Text("unknown".into())),("mp4_codec",2,SqliteValue::Integer(256)),("mp4_movie",1,SqliteValue::Text("18446744073709551616".into())),("mp4_movie",2,SqliteValue::Text("01".into())),("mp4_hevc_array",1,SqliteValue::Integer(99)),("mp4_hevc_array",3,SqliteValue::Integer(2)),("mp4_hevc_array",4,SqliteValue::Integer(256)),("mp4_visual_sample_entry",1,SqliteValue::Integer(65536)),("mp4_visual_sample_entry",12,SqliteValue::Integer(-32769)),("mp4_sample",5,SqliteValue::Integer(2147483648)),("mp4_sample",6,SqliteValue::Integer(2))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(Mp4Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}for table in["mp4_ftyp","mp4_movie","mp4_movie_matrix","mp4_codec","mp4_track_metadata","mp4_visual_sample_entry","mp4_track_matrix"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.remove(0);assert!(Mp4Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());}
#[test]
fn sqlite_snapshot_mp4_large_intrinsic_copy_and_occurrences_remain_cancellable(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🎛️control.json")).unwrap();let mut snapshot=fixture();snapshot.tracks[0].samples=vec![snapshot.tracks[0].samples[0].clone();corpus["entityCount"].as_u64().unwrap()as usize];let mut reached=false;assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut|event|{if event.completed>=corpus["cancelAt"].as_u64().unwrap()as usize{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);snapshot=fixture();snapshot.tracks[0].samples[0].data=vec![255;corpus["largeBlobBytes"].as_u64().unwrap()as usize];let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>0&&event.total==0{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{Mp4Snapshot::from_sqlite_database(&database,&mut control).is_err()});assert!(reached);}}
#[test]
fn sqlite_snapshot_mp4_actual_erased_capability_preserves_binary_and_text(){use semio_framework_os_kernel::{io::{ArtifactDialect,IoPayload},sqlite_snapshot::SnapshotEncoding};let snapshot=fixture();let codec=(crate::native_codecs()[0].codec)();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.mp4".into(),standard:"isobmff".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<Mp4Snapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(<Mp4Snapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=(provider.import)(&codec.schema,&dialect,import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(match restored{IoPayload::Binary(bytes)=><Mp4Snapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><Mp4Snapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()},snapshot);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_mp4_actual_declaration_preserves_full_owned_intermediate_state(){use semio_framework_os_kernel::{io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::SnapshotEncoding};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("MP4 SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let snapshot=fixture();let dialect=ArtifactDialect{artifact_kind:"s.stdio.mp4".into(),standard:"isobmff".into(),subset:"*".into()};let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut|event|{phases.push(event.phase);true}).await.unwrap().value;assert_eq!(io_import_sqlite_snapshot::<Mp4Snapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,snapshot);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}
#[test]
fn sqlite_snapshot_mp4_native_and_typescript_exchange_complete_neutral_databases(){use std::{io::Write,process::{Command,Stdio},path::PathBuf};let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let native=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let artifact=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../🟦️.ts");let artifact=std::fs::canonicalize(artifact).unwrap();let snapshot_root=artifact.parent().unwrap().join("🏅️standards/🔖️isobmff/🪆️subsets/✳️any/🧬️schema/📸️snapshot");let physical=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts");let physical=std::fs::canonicalize(physical).unwrap();let script=format!("import assert from'node:assert/strict';const api=await import({});const physical=await import({});const snapshot=api.parseMp4Snapshot(await Bun.file({}).json());const native=await physical.importSqliteDatabase(new Uint8Array(await Bun.stdin.arrayBuffer()));assert.deepEqual(await api.mp4SnapshotFromSqliteDatabase(native),snapshot);const database=await api.mp4SnapshotToSqliteDatabase(snapshot);assert.deepEqual(database,native);await Bun.write(Bun.stdout,await physical.exportSqliteDatabase(database));",serde_json::to_string(&artifact.to_string_lossy()).unwrap(),serde_json::to_string(&physical.to_string_lossy()).unwrap(),serde_json::to_string(&snapshot_root.join("🧫️fixtures/🪶️sqlite/🔣️.json").to_string_lossy()).unwrap());let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&native).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let typescript=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(typescript,database);assert_eq!(Mp4Snapshot::from_sqlite_database(&typescript,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);}

#[test]
fn sqlite_snapshot_mp4_owned_encoding_bounds_precede_printers_and_check_cancellation(){use semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding;let snapshot=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let mut phases=Vec::new();let error=snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut|event|{phases.push(event.phase);true},SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err();assert!(error.contains("native encoding exceeds file byte limit"),"{error}");assert!(phases.contains(&SqliteSnapshotPhase::EncodeNative));let mut large=snapshot.clone();large.tracks[0].samples[0].data=vec![255;131073];let mut reached=false;let result=large.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut|event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>0{reached=true;false}else{true}},SqliteDatabaseLimits::default()));assert!(result.is_err());assert!(reached);}}
#[test]
fn sqlite_snapshot_mp4_shipped_demo_assets_match_owned_native_source(){let snapshot=crate::standards::isobmff::subsets::any::io::decode_mp4(include_bytes!("../../../../📚️examples/🎬️demo/🖼️assets/🎬️.mp4")).unwrap();assert_eq!(<Mp4Snapshot as store::ArtifactDsl>::parse_dsl(include_str!("../../../../📚️examples/🎬️demo/🖼️assets/🗣️.dsl.semio")).unwrap(),snapshot);assert_eq!(<Mp4Snapshot as store::ArtifactPack>::decode_pack(include_bytes!("../../../../📚️examples/🎬️demo/🖼️assets/🎒️.pack.semio")).unwrap(),snapshot);}
#[test]
fn sqlite_snapshot_mp4_native_factory_declares_actual_structural_hash(){let value:serde_json::Value=serde_json::from_str(crate::ARTIFACT_DEFINITION_SCHEMA).unwrap();let codec=(crate::native_codecs()[0].codec)();assert_eq!(semio_framework_hash::hex_lower(&codec.pack_schema_hash),value["codecs"][0]["native_factory"]["pack_schema_hash"].as_str().unwrap());}
